/**
 * @description Tests for business data in the answer or callback: the send hands the transaction to the background
 * job, the job runs the handler (Done or Failed), callbacks, full bodies in Files, and the admin rerun.
 */
@IsTest
private class IntegrationHubBusinessTest {

    private static final String GOOD = '{"status":"SUCCESS","reference":"V-REF","data":{"voucher":"V-1"}}';

    @TestSetup
    static void setup() {
        IntegrationHubTestData.setupAll();
    }

    private static IH_Transaction__c businessTxn(String status, String businessStatus, String responseBody) {
        IH_Transaction__c t = IntegrationHubTestData.newTransaction(IntegrationHubTestData.BUSINESS_KEY, status);
        IntegrationHubData.updateAll(new List<IH_Transaction__c>{ new IH_Transaction__c(Id = t.Id, Business_Status__c = businessStatus,
            Response_Body__c = responseBody, Http_Status_Code__c = 200) });
        return t;
    }

    private static IH_Transaction__c reload() {
        return IntegrationHubTestData.transactions(IntegrationHubTestData.BUSINESS_KEY)[0];
    }

    @IsTest
    static void sendHandsTheAnswerToTheBackgroundJob() {
        System.runAs(IntegrationHubTestData.admin()) {
            Test.setMock(HttpCalloutMock.class, new IntegrationHubTestData.Mock(200, GOOD));
            Test.startTest();
            IntegrationHubTestData.newBusinessEvent();
            IntegrationHub.publish(IntegrationHubTestData.BUSINESS_KEY, new List<SObject>{ IntegrationHubTestData.accounts()[0] });
            Test.stopTest();
            IH_Transaction__c t = reload();
            Assert.areEqual('Success', t.Status__c, 'the delivery status is set as before: ' + t.Error_Message__c);
            Assert.areEqual('V-REF', t.External_Reference_Id__c, 'the reference is stored as before');
            Assert.areEqual('Processing', t.Business_Status__c, 'the handler waits for the background job');
            Assert.areNotEqual('BUSINESS', t.Correlation_Id__c, 'the handler did not run inline');
            Assert.isTrue(t.Request_Url__c.startsWith('POST callout:IH_Test/records/'), 'the method and endpoint are kept: ' + t.Request_Url__c);
        }
    }

    @IsTest
    static void jobRunsTheHandlerAndSetsDone() {
        System.runAs(IntegrationHubTestData.admin()) {
            IntegrationHubTestData.newBusinessEvent();
            IH_Transaction__c t = businessTxn('Success', 'Processing', GOOD);
            Test.startTest();
            System.enqueueJob(new IntegrationHubBusiness(new List<Id>{ t.Id }));
            Test.stopTest();
            IH_Transaction__c after = reload();
            Assert.areEqual('Done', after.Business_Status__c, 'the handler ran: ' + after.Business_Error__c);
            Assert.areEqual('Voucher V-1', after.Business_Result__c, 'the result line is saved');
            Assert.areEqual(1, after.Business_Runs__c, 'one run is counted');
            Assert.areEqual('BUSINESS', after.Correlation_Id__c, 'field changes of the handler are saved');
            Assert.areEqual('Success', after.Status__c, 'the delivery status is not changed');
        }
    }

    @IsTest
    static void handlerErrorSetsFailedAndKeepsStatus() {
        System.runAs(IntegrationHubTestData.admin()) {
            IntegrationHubTestData.newBusinessEvent();
            IH_Transaction__c t = businessTxn('Success', 'Processing', '{"status":"SUCCESS","data":{"fail":true}}');
            IH_Transaction__c notWaiting = businessTxn('Success', 'Done', GOOD);
            Test.startTest();
            System.enqueueJob(new IntegrationHubBusiness(new List<Id>{ t.Id, notWaiting.Id }));
            Test.stopTest();
            Map<Id, IH_Transaction__c> byId = new Map<Id, IH_Transaction__c>(IntegrationHubTestData.transactions(IntegrationHubTestData.BUSINESS_KEY));
            IH_Transaction__c failed = byId.get(t.Id);
            Assert.areEqual('Failed', failed.Business_Status__c, 'a handler error is Failed');
            Assert.isTrue(failed.Business_Error__c.contains('Business data rejected'), 'the error is kept');
            Assert.areEqual('Success', failed.Status__c, 'the delivery status is not changed by a handler error');
            Assert.areEqual(1, failed.Business_Runs__c, 'the failed run is counted');
            Assert.isNull(byId.get(notWaiting.Id).Business_Runs__c, 'only Processing transactions are run');
        }
    }

    @IsTest
    static void longCallbackIsKeptInAFileAndRunInTheBackground() {
        System.runAs(IntegrationHubTestData.admin()) {
            IH_Event__c ev = IntegrationHubTestData.newBusinessEvent();
            ev.Expects_Callback__c = true;
            IntegrationHubData.updateAll(new List<IH_Event__c>{ ev });
            IH_Transaction__c t = IntegrationHubTestData.newTransaction(IntegrationHubTestData.BUSINESS_KEY, 'Sent');
            String body = '{"status":"SUCCESS","data":{"voucher":"V-2","pad":"' + 'x'.repeat(140000) + '"}}';
            RestRequest req = new RestRequest();
            req.requestURI = '/services/apexrest/integrationhub/v1/callback/' + t.Id;
            req.httpMethod = 'PATCH';
            req.requestBody = Blob.valueOf(body);
            RestContext.request = req;
            RestContext.response = new RestResponse();
            Test.startTest();
            IntegrationHubInboundApi.callback();
            Test.stopTest();
            Map<String, Object> answer = (Map<String, Object>) JSON.deserializeUntyped(RestContext.response.responseBody.toString());
            Assert.areEqual('Processing', answer.get('business'), 'the answer says the business data is being processed');
            IH_Transaction__c after = reload();
            Assert.areEqual('Success', after.Status__c, 'the callback status is applied');
            Assert.areEqual(131072, after.Callback_Body__c.length(), 'the field keeps the first part');
            Assert.areEqual('Done', after.Business_Status__c, 'the job read the full body from the File: ' + after.Business_Error__c);
            Assert.areEqual('Voucher V-2 (callback)', after.Business_Result__c, 'the handler got the callback data');
            Assert.isNotNull(IntegrationHubBodyFiles.fileIds(t.Id).get(IntegrationHubBodyFiles.CALLBACK_PREFIX), 'the full body is a File');
        }
    }

    @IsTest
    static void rerunOnlyForAdminsAndFailed() {
        System.runAs(IntegrationHubTestData.admin()) {
            IntegrationHubTestData.newBusinessEvent();
        }
        IH_Transaction__c t;
        System.runAs(IntegrationHubTestData.admin()) {
            t = businessTxn('Success', 'Failed', GOOD);
        }
        System.runAs(IntegrationHubTestData.reader()) {
            try {
                IntegrationHubBusiness.rerun(t.Id);
                Assert.fail('a reader cannot rerun');
            } catch (AuraHandledException e) {
                Assert.isTrue(e.getMessage().contains('Admin'), 'the error names the permission');
            }
        }
        IntegrationHubMonitorController.adminInTest = true;
        System.runAs(IntegrationHubTestData.admin()) {
            Test.startTest();
            IntegrationHubBusiness.rerun(t.Id);
            Assert.areEqual('Processing', reload().Business_Status__c, 'a rerun waits for the job');
            Test.stopTest();
            IH_Transaction__c after = reload();
            Assert.areEqual('Done', after.Business_Status__c, 'the rerun ran the handler');
            List<IH_Attempt__c> attempts = (List<IH_Attempt__c>) IntegrationHubData.query(
                'SELECT Kind__c, Outcome__c, Http_Status_Code__c FROM IH_Attempt__c WHERE Transaction__c = :id', new Map<String, Object>{ 'id' => t.Id });
            Assert.areEqual(1, attempts.size(), 'the rerun is logged');
            Assert.areEqual('Handler Rerun', attempts[0].Kind__c, 'as a handler rerun');
            Assert.areEqual('Done', attempts[0].Outcome__c, 'with its result');
            Assert.isNull(attempts[0].Http_Status_Code__c, 'and no HTTP status');
            try {
                IntegrationHubBusiness.rerun(t.Id);
                Assert.fail('only Failed can be rerun');
            } catch (AuraHandledException e) {
                Assert.isTrue(e.getMessage().contains('Failed'), 'the rule is explained');
            }
        }
    }

    @IsTest
    static void recoveryMarksStuckProcessingFailed() {
        System.runAs(IntegrationHubTestData.admin()) {
            IntegrationHubTestData.newBusinessEvent();
            IH_Transaction__c t = businessTxn('Success', 'Processing', GOOD);
            IntegrationHubBusiness.Recovery recovery = new IntegrationHubBusiness.Recovery(new List<Id>{ t.Id });
            recovery.execute(new IntegrationHubTestData.StubFinalizerContext(ParentJobResult.SUCCESS));
            Assert.areEqual('Processing', reload().Business_Status__c, 'a successful job changes nothing');
            recovery.execute(new IntegrationHubTestData.StubFinalizerContext(ParentJobResult.UNHANDLED_EXCEPTION));
            IH_Transaction__c after = reload();
            Assert.areEqual('Failed', after.Business_Status__c, 'a dead job marks its transactions Failed');
            Assert.isTrue(after.Business_Error__c.contains('Job died'), 'the reason is kept');
        }
    }

    @IsTest
    static void dataIsTheDataObjectOnly() {
        System.runAs(IntegrationHubTestData.admin()) {
            Assert.isNull(IntegrationHubBusiness.dataOf(null), 'no body');
            Assert.isNull(IntegrationHubBusiness.dataOf('not json'), 'not JSON');
            Assert.isNull(IntegrationHubBusiness.dataOf('{"data":[1]}'), 'data must be an object');
            Assert.areEqual('V-1', IntegrationHubBusiness.dataOf(GOOD).get('voucher'), 'the data object is read');
            IntegrationHubBusiness.enqueue(null);
            Assert.isNull(IntegrationHubBodyFiles.fileFor(null, 'x', 'y'), 'no File without a transaction');
        }
    }
}
